{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "Urapidil, a basic aromatic amine, had absolute oral bioavailability of 78% (72-84%) in healthy volunteers; with assay-transfer 0.9821, this strongly supports high F for the query's similar basic amine/aromatic scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Donepezil, a lipophilic basic amine with aromatic groups, showed complete (~100%) oral bioavailability in humans; assay-transfer 0.9818 supports high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Diphenhydramine, a tertiary amine antihistamine structurally reminiscent of the query, had absolute oral bioavailability 42±5% in elderly subjects, with other reports ranging 35-72%, all above the 20% threshold; assay-transfer 0.9791 supports high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Moexipril, the lowest-F analogue in the set, still had 22% oral bioavailability, just above the 20% threshold; assay-transfer 0.9788 indicates even the least favorable close analogue does not support low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Benazeprilat had absolute bioavailability of 27-28.5%, above the 20% threshold; assay-transfer 0.9824 supports high F for the query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All retrieved experimental analogues have absolute oral bioavailability values above 20% (range 22-100%), with very high assay-transfer scores (~0.98). The query's lipophilic basic amine structure is consistent with these high-F compounds, and no affirmative evidence supports F<20%. Therefore predict high.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the query molecule itself.",
    "First-pass metabolism for this specific diamine could differ from the analogues, but no affirmative evidence indicates low bioavailability.",
    "No data on solubility or formulation effects for the query were provided."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

